/* ===== Learn Islam guides for the kids corner: [id, title, icon, [[section title, [paragraphs]]]] ===== */
(function(){ window.M = window.M || {}; M.LEARN = [["pillars", "أركان الإسلام الخمسة", "crescent", [["", ["أركان الإسلام الخمسة أساس عبادة المسلم وحياته. بها يظهر الإيمان في العمل، وتعيننا على التقرب إلى الله. تعلّمها خطوةً خطوة."]], ["الشهادتان", ["الشهادتان إقرار صادق بأن الله وحده المستحق للعبادة، وأن محمدًا رسول الله ﷺ. وهما أساس الإسلام. أَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ. يدخل الإنسان في الإسلام بالإيمان بمعناهما والنطق بهما صادقًا."]], ["إقامة الصلاة", ["يصلي المسلم خمس صلوات مفروضة كل يوم: الفجر، والظهر، والعصر، والمغرب، والعشاء. لكل صلاة وقتها، وفيها تلاوة وذكر وحركات منها الركوع والسجود. استعد بالوضوء عند الحاجة، واستقبل القبلة، وصلّ بإخلاص. تعلّم بالتدرّج وصلّ بحسب استطاعتك؛ فمن عجز عن القيام صلى بما يناسب قدرته."]], ["إيتاء الزكاة", ["الزكاة حق واجب في أموال معينة، يُعطى لمستحقيه ومنهم المحتاجون. وهي تذكّر المسلم برعاية الآخرين وتطهّر المال. وتختلف عن الصدقة التطوعية. في النقود وبعض المدخرات تكون الزكاة غالبًا اثنين ونصفًا في المائة عند بلوغ النصاب وتحقّق شرط مرور السنة القمرية. ولأنواع المال الأخرى أحكام مختلفة؛ فاستعن بمن يعلم أحكام الزكاة عند حسابها."]], ["صوم رمضان", ["يصوم المسلمون في رمضان من طلوع الفجر الصادق إلى غروب الشمس، فيمتنعون عن الطعام والشراب وسائر المفطرات تقربًا إلى الله. ويعلّمنا الصيام الصبر والشكر والإحساس بالآخرين. للمريض والمسافر رخصة الفطر وقضاء الأيام لاحقًا. وللحيض والعجز المستمر عن الصيام وأحوال أخرى أحكامها؛ فاسأل أهل العلم عمّا يناسب حالتك."]], ["حج البيت", ["الحج هو قصد بيت الله الحرام في مكة لأداء مناسك مخصوصة في أيام الحج من ذي الحجة. ومن أعماله الطواف بالكعبة، والسعي بين الصفا والمروة، والوقوف بعرفة. يجب الحج مرة واحدة في العمر على المسلم المستطيع بدنيًا وماليًا. ومن لا يستطيع لا يجب عليه حتى تتحقق استطاعته.", "تعلّم على مهل؛ فالله رحيم، ويمكنك سؤال معلّم موثوق أو مسجد قريب عمّا يتعلق بحالتك. المصدر: صحيح البخاري ٨؛ القرآن الكريم: البقرة ١٨٥، وآل عمران ٩٧، والتوبة ٦٠."]]]], ["taharah", "الطهارة", "drop", [["", ["دليل تعليمي من مصادر أهل السنة، يشرح الأصول والمسائل الشائعة مع التنبيه إلى الخلاف المعتبر. الحالات الفردية والأعذار تحتاج سؤال عالم موثوق."]], ["ما الطهارة؟", ["الطهارة تشمل طهارة القلب، والنظافة، والطهارة الشرعية للعبادة. وهذا الباب يشرح طهارة البدن والملابس والمكان، ورفع الحدث. الجنابة والحيض والنفاس حالات شرعية طبيعية لا تجعل الإنسان نجسًا ولا تُخرجه من الإسلام. [1، 13]"]], ["الفرق بين الحدث والنجاسة", ["الحدث وصف شرعي يمنع بعض العبادات حتى يُرفع؛ فالأصغر يرفع بالوضوء، والأكبر بالغسل، ويقوم التيمم مقامهما عند العذر بشروطه. أما النجاسة فهي عين كالبول تصيب البدن أو الثوب أو المكان؛ تزال عن موضعها. وقد يجتمع الأمران، وقد يوجد أحدهما دون الآخر. [1، 2]"]], ["الماء وإزالة النجاسة", ["الأصل استعمال الماء الطهور. إذا تيقنت نجاسة في البدن أو الثوب أو موضع الصلاة فاغسل الموضع حتى تزول عينها قدر المستطاع؛ لا يلزم غسل الثوب كله لمجرد إصابة جزء منه. يُعفى عما يشق زواله من أثر يسير بعد الغسل بحسب تفصيل الفقهاء. لا تُحوِّل شكًا عابرًا إلى حكم بالنجاسة؛ فالأصل الطهارة. [2، 3]"]], ["الاستنجاء بعد قضاء الحاجة", ["أزل أثر البول أو الغائط بالماء، ويجوز الاستجمار بمادة طاهرة مناسبة تزيل الخارج وفق شروطه؛ والماء أكمل. امسح أو اغسل الموضع الظاهر بلا أذى أو مبالغة، ثم اغسل يديك. الاستنجاء يزيل النجاسة، ولا يغني وحده عن الوضوء إذا أردت الصلاة. [3]"]], ["الحدث الأصغر ونواقض الوضوء", ["من أسبابه خروج البول أو الغائط أو الريح من السبيلين، والنوم المستغرق الذي يزول معه الإحساس، وزوال العقل. يختلف الفقهاء في بعض التفاصيل كمسّ الفرج أو لمس الزوجة؛ لا تجعل مسائل الخلاف سببًا للوسواس. خروج شيء متيقن يختلف عن مجرد الإحساس أو الشك. [1، 2]"]], ["كيف أتوضأ؟", ["انوِ بقلبك العبادة واذكر اسم الله، ثم اغسل كفيك، وتمضمض واستنشق واستنثر، واغسل وجهك، ثم يديك مع المرفقين، وامسح رأسك وأذنيك، واغسل قدميك مع الكعبين، مبتدئًا باليمين. غسل الأعضاء ثلاثًا سنة في مواضعها وليس شرطًا لصحة كل غسل. يختلف أهل السنة في بعض الفرائض والسنن والتفاصيل؛ راجع دليل الوضوء المصور. [1، 4]"]], ["الحدث الأكبر وموجبات الغسل", ["يجب غسل الجنابة بالجماع مع حصول الإيلاج ولو بلا إنزال، أو بخروج المني بشهوة، ويجب بعد الاحتلام عند رؤية المني. فإذا رأى المرء حلمًا ولم يجد بللًا فلا غسل لمجرد الحلم. وتغتسل المرأة بعد انقطاع الحيض أو النفاس وظهور الطهر. مسائل خروج المني بغير لذة أو البلل غير المتيقن فيها تفصيل وخلاف؛ يُسأل عنها عالم موثوق. [1، 5، 6]"]], ["صفة الغسل المجزئ والكامل", ["للغسل المجزئ اقصد التطهر للعبادة، وأزل ما يمنع وصول الماء، وعمِّم الماء على جميع البدن والشعر وأصوله، بما فيها الثنايا الظاهرة، وتمضمض واستنشق احتياطًا واتباعًا لمن أوجبهما. النية شرط عند الجمهور، وعند الحنفية ليست شرطًا لصحة غسل الجنابة؛ فلا يُحكم ببطلان غسل سابق لمجرد ذلك. الاستحمام للنظافة لا يرفع الحدث بالضرورة؛ وقد يجزئ الاستحمام نفسه للغسل الشرعي إذا تحققت شروطه في المذهب المتبع. الصابون والشامبو ليسا شرطًا. وبعد غسل صحيح لا يلزم وضوء آخر دائمًا إذا لم يقع ناقض، وفي التفاصيل خلاف. [1، 7]"]], ["الغسل الكامل خطوة بخطوة", ["اغسل اليدين ثم موضع الأذى، وتوضأ وضوء الصلاة، ثم خلّل أصول الشعر وصب الماء على الرأس ثلاثًا، وأفض الماء على سائر البدن، مع تعهد ما قد يغفل عنه من الثنايا والقدمين. يجوز تأخير غسل القدمين إلى آخر الغسل. هذه صفة مسنونة؛ لا يلزم لكل جزء ثلاثة غسلات لصحة الغسل. احفظ ستر العورة واقتصد في الماء. [7]"]], ["الشعر والضفائر والحواجز", ["يجب وصول الماء إلى أصول الشعر والبشرة الظاهرة في الغسل. لا يلزم نقض الضفائر في غسل الجنابة إذا وصل الماء إلى الأصول؛ وفي غسل الحيض توجد تفاصيل وخلاف، فإن منعت الضفائر وصول الماء حُلّت. أزل الطلاء أو اللاصق الذي يمنع الماء من البشرة أو الأظفار، أما اللون المجرد الذي لا يشكل حاجزًا فلا يمنع وصوله. [7، 8]"]], ["المني", ["المني من الرجل أو المرأة قد يخرج عند الشهوة الكبرى ويعقب خروجه فتور؛ وقد تختلف صفاته من شخص لآخر. خروجه بشهوة أو وجوده بعد الاحتلام يوجب الغسل. أما خروجه في اليقظة بغير شهوة بسبب مرض ونحوه فلا يوجب الغسل عند الجمهور ويُنقض به الوضوء، بينما يوجب الشافعية الغسل عند تحقق كونه منيًا؛ للحالة تفاصيل تُسأل. واختلف الفقهاء في نجاسة المني نفسه: فالشافعية والحنابلة يقولون بطهارته، والحنفية والمالكية بنجاسته؛ وغسل موضعه من الثوب خروج من الخلاف. لا يُبنى الحكم على اللون وحده. [5]"]], ["المذي", ["المذي سائل رقيق لزج قد يخرج عند الإثارة دون دفق المني أو فتور يعقبه. ينقض الوضوء ولا يوجب الغسل وحده. اغسل الموضع المصاب من البدن، واغسل ما أصاب الثوب، ثم توضأ للصلاة. ورد في حق الرجل غسل الذكر، وفي بعض الروايات ذكر الأنثيين؛ ويُتبع ما يتيسر وفق المذهب المتبع. [6]"]], ["الودي وإفرازات أخرى", ["الودي سائل غالبًا أبيض ثخين قد يخرج بعد البول؛ حكمه حكم البول من حيث غسل الموضع وما أصابه والوضوء، ولا يوجب الغسل وحده. الإفرازات المهبلية المعتادة ليست حيضًا أو منيًا لمجرد وجودها؛ اختلف الفقهاء في نجاستها، ومن أهل العلم من رجح طهارتها مع انتقاض الوضوء بخروجها. والمستمر منها له أحكام صاحب العذر. لا يلزم التفتيش المتكرر؛ وعند تغير الإفرازات أو الحاجة الطبية يُستشار الطبيب."]], ["الحيض والطهر منه", ["الحيض دم طبيعي، ووجوده ليس ذنبًا ولا نقصًا في كرامة المرأة. أثناء الحيض يحرم الجماع وتُترك الصلاة والصوم، وتقضي أيام الصيام الواجبة بعد رمضان ولا تقضي الصلوات الفائتة. إذا تحقق انقطاعه بعلامة الطهر المعتادة، كالجفاف التام أو القَصّة البيضاء لمن تعرفها، اغتسلت وصلت. مسائل اختلاف الدم والمدة والصفرة والكدرة لها تفصيل؛ يُسأل عنها بحسب الحالة والمذهب. [9، 10]"]], ["النفاس والاستحاضة", ["النفاس دم يعقب الولادة؛ تمتنع النفساء عن الصلاة والصوم وتقضي الصيام دون الصلاة. إذا رأت الطهر اغتسلت وصلت ولو قبل إكمال مدة شائعة؛ واختلف الفقهاء في أكثر مدته وتفاصيل الدم العائد. الاستحاضة نزيف آخر غير الحيض والنفاس، فلا تُترك الصلاة والصوم بسببه وحده؛ يُرجع للعادة والتمييز وأهل العلم لتحديد أيام كل منهما، مع الاستعانة بالطبيب عند الحاجة. [9، 10]"]], ["السلس والجرح والمرض", ["من يستمر معه البول أو الريح أو الدم بحيث لا يجد وقتًا معتادًا يسع الطهارة والصلاة، يتحفظ بما يستطيع ويعمل بأحكام صاحب العذر، ومنها الوضوء بعد دخول وقت الصلاة عند من يقول بذلك؛ تختلف التفاصيل، فاسأل عالمًا دون ترك الصلاة. صاحب كيس الفغرة الطبية يتحفظ وينظف أو يفرغ الكيس بحسب استطاعته وإرشاد طبيبه، ويسأل عن حكم استمرار الخارج ولا يضرّه ما عجز عن منعه. تُغسل الأعضاء السليمة، وقد يُمسح على الضماد أو يُتيمم بحسب حال الجرح والضرر وحكم المذهب. [1]"]], ["التيمم عند العذر", ["عند فقد الماء بعد طلبه بحسب الاستطاعة، أو تعذر استعماله لمرض أو ضرر معتبر، يجوز التيمم بقصد الطهارة وبصعيد طاهر وفق التفصيل الفقهي: يضرب بكفيه الصعيد ثم يمسح وجهه ويديه. اختلفت المذاهب في بعض صفته وحدّ مسح اليدين، وما يصح التيمم به، وأثر وجود الماء بعده؛ يُعمل بما يفتي به أهل العلم في الحالة. [1]"]], ["الطهارة والصلاة", ["لصحة الصلاة تُطلب الطهارة من الحدث، وإزالة النجاسة عن البدن والثوب وموضع الصلاة بحسب الاستطاعة والتفصيل. إذا وقع ناقض متيقن أثناء الصلاة انصرف وتطهر ثم أعادها. من صلى جاهلًا بالنجاسة أو ناسيًا لها، أو عجز عن إزالتها، فله أحكام وخلاف معتبر؛ لا تُعمَّم الإعادة دون سؤال. لا تنقض الوضوء لمجرد الشك. [1، 2]"]], ["الحج والعمرة والطواف", ["الإحرام والوقوف بعرفة والسعي لا يشترط لها الوضوء أو الغسل، وإن استُحبت الطهارة؛ ويجوز إحرام الحائض والنفساء. مع أن الوضوء ليس شرطًا مستقلًا للسعي، فإن سعي العمرة يأتي بعد طوافها الصحيح؛ وتختلف تفاصيل تقديم بعض أعمال الحج. أما الطواف فالطهارة من الحدث شرط عند جمهور الفقهاء، وللحنفية تفصيل آخر؛ فمن أحدث أثناء الطواف أو شق عليه التطهر يسأل مفتيًا عن الإكمال أو الإعادة بحسب حاله. الحائض تؤخر طواف البيت حتى تطهر وتغتسل، وتؤدي ما يمكنها من بقية المناسك؛ وللضرورة أحكام يقدرها أهل العلم. [11]"]], ["الصيام والزكاة والشهادتان", ["الحدث الأصغر أو الجنابة لا يبطلان الصوم بذاتهما، ومن أصبح جنبًا صح صومه ويغتسل للصلاة. وإذا انقطع الحيض أو النفاس قبل الفجر ونوت الصوم صح وإن اغتسلت بعد الفجر، مع أداء الصلاة في وقتها. أما نزول الحيض أو النفاس في نهار الصوم فيمنع استمرار صوم ذلك اليوم ويُقضى في الصوم الواجب. الشهادتان والزكاة لا يُشترط لهما الوضوء أو الغسل، والنجاسة لا تُبطل الإسلام. [9، 12]"]], ["المصحف والذكر والمسجد", ["يجوز ذكر الله والدعاء دون وضوء. جمهور الفقهاء يشترطون الطهارة من الحدث لمس المصحف الورقي مباشرة، وللقراءة عن ظهر قلب أو من الهاتف وللحائض والجنب تفاصيل وخلاف معتبر؛ فليتبع السائل ما يفتيه به عالم موثوق. وللمكث في المسجد للجنب والحائض تفصيل، ولا ينبغي تعميم الأحكام دون بيان أحوال الحاجة والخلاف."]], ["الشك واليقين وتجنب الوسواس", ["الأصل بقاء الطهارة حتى يتيقن الناقض؛ ومجرد احتمال البلل أو حركة البطن أو الشك في عدد الغسلات بعد الفراغ لا يوجب التفتيش المستمر أو تكرار الوضوء والغسل. لا يُشترط الجزم بالمبالغات؛ اغسل بما يحقق وصول الماء ثم امضِ في عبادتك. من ابتُلي بوسواس متكرر فليأخذ بالتيسير المعتبر ويستعن بمختص. [2]"]], ["المراجع السنية الموثقة", ["[1] القرآن الكريم: المائدة 5:6، النساء 4:43، البقرة 2:222. [2] صحيح البخاري 137: اليقين والشك في الحدث. [3] صحيح البخاري 227: غسل دم الحيض عن الثوب. [4] صحيح البخاري 159: صفة وضوء النبي ﷺ. [5] صحيح مسلم 349 و313a: الغسل بالجماع والاحتلام. [6] صحيح مسلم 303a: حكم المذي. [7] صحيح البخاري 248: صفة غسل الجنابة. [8] صحيح مسلم 330a: غسل الشعر المضفور. [9] صحيح مسلم 335c: قضاء صوم الحائض. [10] صحيح البخاري 331: الحيض والطهر. [11] صحيح البخاري 1650: مناسك الحائض والطواف. [12] صحيح مسلم 1109a: صيام من أصبح جنبًا. [13] صحيح البخاري 283: المؤمن لا ينجس."]]]], ["wudu", "الوضوء", "drop", [["", ["الوضوء طهارة وعبادة. يتبع هذا الدليل خطوات الدرس الإحدى عشرة، ويعرض أهم أحكام الوضوء عند أهل السنة للمبتدئ والمتعلم. تختلف المذاهب السنية المعتبرة في بعض التفاصيل؛ ويمكن سؤال معلّم موثوق عمّا يتعلق بحالتك."]], ["متى نتوضأ وكيف نستعد؟", ["يُحتاج إلى الوضوء للصلاة عند حصول الحدث الأصغر. ومن بقي على وضوئه لا يلزمه أن يعيده لكل صلاة، وإن كان تجديده مستحبًّا. أما الحدث الأكبر فتجب منه الطهارة بالغسل، ولا يكفي عنه الوضوء وحده. استعمل ماءً طهورًا، وبعد قضاء الحاجة أزل أثر البول أو الغائط قبل الوضوء. أزل ما يمنع وصول الماء إلى الجلد والأظافر، كطلاء الأظافر العازل والدهان السميك والغراء؛ أما مجرد اللون الذي لا يشكّل طبقة عازلة فليس كذلك بالضرورة. حرّك الخاتم الضيق ليصل الماء تحته، واحفظ خصوصيتك واستُر عورتك."]], ["الخطوة ١: النية", ["انوِ بقلبك الطهارة للعبادة؛ فالنية محلها القلب ولا تحتاج إلى صيغة منطوقة مخصوصة. اختلفت المذاهب السنية في حكمها، والأيسر والأحوط أن تستحضرها."]], ["الخطوة ٢: التسمية", ["قل «بسم الله» قبل البدء. وإذا نسيت فتابع وضوءك. اختلف علماء السنة في حكم التسمية؛ فلا تجعل الخلاف أو الشك سببًا للمشقة."]], ["الخطوة ٣: غسل الكفين", ["اغسل الكفين إلى الرسغين ثلاث مرات، وابدأ باليمين، وأوصل الماء بين الأصابع. وهذا الغسل في البداية غير غسل اليدين إلى المرفقين في الخطوة السابعة."]], ["الخطوة ٤: المضمضة", ["خذ ماءً في فمك، وأدِره ثم أخرجه، وكرّر حتى ثلاث مرات. ويجوز أخذ الماء للفم والأنف من كف واحدة. إذا كنت صائمًا فتمضمض برفق حتى لا تبتلع الماء."]], ["الخطوة ٥: الاستنشاق والاستنثار", ["أدخل قليلًا من الماء في الأنف برفق باليد اليمنى، ثم أخرجه من الأنف مستعينًا باليد اليسرى، وكرّر حتى ثلاث مرات. لا تبالغ في الاستنشاق إذا كنت صائمًا أو كان ذلك يضرك."]], ["الخطوة ٦: غسل الوجه", ["اغسل وجهك كاملًا من منبت الشعر المعتاد إلى أسفل الذقن، ومن الأذن إلى الأذن، وأوصل الماء إلى البشرة وأطراف الوجه. تُغسل اللحية الخفيفة إلى ما تحتها، وتُغسل ظواهر اللحية الكثيفة مع تخليلها بالأصابع المبللة. وكرّر الغسل حتى ثلاث مرات."]], ["الخطوة ٧: غسل اليدين إلى المرفقين", ["اغسل اليد اليمنى من أطراف الأصابع إلى المرفق مع إدخال المرفق في الغسل، ثم اليسرى كذلك، حتى ثلاث مرات لكل يد. تأكد من وصول الماء إلى الكفين والرسغين والمرفقين، وإن غسلت الكفين في البداية."]], ["الخطوة ٨: مسح الرأس", ["بيدين مبللتين امسح الرأس مرة واحدة: ابدأ بالمقدّمة، واذهب باليدين إلى مؤخرة الرأس، ثم ارجع إلى موضع البداية. المقصود المسح لا غسل الرأس ثلاثًا. ولا يلزم صاحب الشعر الطويل نقض ضفائره لمجرد الوضوء. اختلفت المذاهب السنية في القدر المجزئ، ومسح الرأس كله هو الطريقة المعروضة هنا."]], ["الخطوة ٩: مسح الأذنين", ["بأصابع مبللة امسح باطن الأذنين وظاهرهما مرة واحدة؛ يمكن مسح الداخل بالسبابتين والظاهر بالإبهامين. لا تصب الماء في قناة الأذن ولا تدخل الأصابع بما يسبب أذًى."]], ["الخطوة ١٠: غسل القدمين", ["اغسل القدم اليمنى مع الكعبين، ثم اليسرى كذلك، حتى ثلاث مرات لكل قدم. أوصل الماء إلى العقبين وباطن القدم وبين الأصابع، ولا تترك موضعًا جافًّا."]], ["الخطوة ١١: الذكر بعد الوضوء", ["بعد إتمام الوضوء يُستحب أن تقول: أَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، اللَّهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِينَ. النطق بالحروف اللاتينية: ⁦Ashhadu an la ilaha illa Allahu wahdahu la sharika lah, wa ashhadu anna Muhammadan ‘abduhu wa rasuluh. Allahumma ij‘alni min at-tawwabina waj‘alni min al-mutatahhirin.⁩ هذا الذكر مستحب، وتركه لا يبطل الوضوء."]], ["ما الذي يجب إتمامه؟", ["ذكر القرآن غسل الوجه، وغسل اليدين مع المرفقين، ومسح الرأس، وغسل القدمين مع الكعبين. يجب وصول الماء إلى كامل الموضع الذي يُغسل. وتكفي غسلة واحدة مستوعبة لكل موضع واجب؛ وتكرار غسل الأعضاء حتى ثلاث مستحب. ولا يُجعل المسح كالغسل. تختلف المذاهب السنية في بعض التفاصيل، ومنها النية والمضمضة والاستنشاق والترتيب والموالاة ومقدار مسح الرأس. واتّباع التسلسل الكامل أعلاه يعين المتعلم على الوضوء الصحيح، دون اعتبار كل مستحب فرضًا متفقًا عليه."]], ["ما الذي ينقض الوضوء عادةً؟", ["ينقض الوضوء عادةً خروج البول أو الغائط أو الريح من موضعها المعتاد، وكذلك المذي ونحوه من الخارج. وينقضه زوال الوعي بالإغماء أو السكر، والنوم العميق الذي يذهب معه الإحساس. الحدث الأصغر يحتاج إلى إزالة النجاسة والوضوء؛ أما الجماع أو خروج المني فيحتاج إلى الغسل. وللحيض والنفاس أحكامهما، ويجب الغسل بعد انقطاعهما."]], ["مسائل اختلف فيها علماء السنة", ["اختلفت المذاهب السنية في النوم اليسير، ومس الفرج مباشرة، وتلامس بشرة الرجل والمرأة، وخروج الدم أو القيء من غير السبيلين، وأكل لحم الإبل. فمثلًا يرى بعضهم وجوب الوضوء من لحم الإبل، ولا يراه آخرون. تعلّم ما يبيّنه لك معلّم سني موثوق أو المذهب الذي تتبعه، ولا تنكر على من اتبع قولًا معتبرًا."]], ["أمور لا تنقض الوضوء بمجردها", ["تغيير الملابس وقص الشعر أو الأظافر والأكل المعتاد لا تنقض الوضوء بمجردها. ولمس النجاسة لا ينقض الوضوء في نفسه، لكن تُغسل النجاسة من الموضع المصاب قبل الصلاة. ومن تيقّن الطهارة لا يزول يقينه بمجرد الشك أو الإحساس بحركة في البطن. يرى جمهور علماء السنة عدم جواز مس المصحف الورقي مباشرة بغير طهارة، مع وجود خلاف واستثناءات عند أهل العلم. والهاتف الذي يعرض القرآن ليس مصحفًا ورقيًّا؛ فيجوز لمن عليه حدث أصغر القراءة منه دون وضوء. وللحدث الأكبر أحكام أخرى."]], ["أخطاء ومكروهات ومحظورات", ["لا تترك عضوًا واجبًا جافًّا عمدًا، ولا تصلِّ عالمًا بترك الطهارة اللازمة، ولا تكشف عورتك للآخرين بلا حاجة معتبرة. تجنّب إيذاء النفس وإضاعة الماء؛ فالزيادة على الثلاث بلا سبب والإسراف خلاف السنة، وقد يكون الإسراف الشديد إثمًا. الكلام أثناء الوضوء ليس محرّمًا في ذاته، ولا تسترسل في التكرار بسبب الوسواس. والمعصية الأخرى لا تبطل الوضوء الصحيح تلقائيًّا."]], ["المرض والجبيرة والخف والتيمم", ["عند عدم وجود الماء أو الخوف من الضرر باستعماله، يُشرع التيمم بالصعيد الطيب بشروطه؛ فتعلّم صفته وأحكامه. وفي الجرح أو الضماد اللازم طبيًّا يُسأل أهل العلم عن غسل ما يمكن غسله والمسح أو التيمم عند الحاجة، ولا يُنزع الضماد إذا كان نزعه يسبب ضررًا. المسح على الخفين أو ما يصح المسح عليه رخصة لها شروط، منها لبسهما بعد تمام الطهارة ومراعاة المدة المعتبرة. وتختلف التفاصيل بين المذاهب السنية؛ فاسأل عن حالتك."]], ["الصلاة والشك والأحوال الخاصة", ["إذا رأيت موضعًا جافًّا فاتك أثناء الوضوء فأكمله؛ وإن تذكّرته بعد زمن طويل أو بعد الصلاة فاسأل عن الحكم، لأن المذاهب تختلف في الموالاة. ولمن لديه عذر مستمر كسلس البول أحكام خاصة؛ فاسأل ولا تترك الصلاة. يتعلم الأطفال بالتدرّج، ويتطهر ويصلي ذو الإعاقة بحسب استطاعته. تجنّب التفتيش المتكرر والوسواس، واطلب المساعدة عند الحاجة.", "المصادر الأساسية: القرآن الكريم، المائدة ٦؛ صحيح البخاري ١٣٧ و١٥٧ و١٥٩ و١٨٥؛ صحيح مسلم ٢٣٤ و٣٦٠؛ جامع الترمذي ٥٥. وتُراجع تفاصيل الأحكام والخلاف في كتب الفقه السني. قد يختلف ترقيم الأحاديث بين الطبعات."]]]], ["prayer", "الصلاة", "rug", [["", ["تعلّم الصلوات الخمس خطوة بخطوة. يعرض هذا الدليل طريقة سنية شائعة، مع وجود اختلاف معتبر بين المذاهب السنية في بعض التفاصيل. صلِّ بحسب استطاعتك، واسأل معلّمًا موثوقًا عند الحاجة. إِنَّ الصَّلَاةَ كَانَتْ عَلَى الْمُؤْمِنِينَ كِتَابًا مَوْقُوتًا سورة النساء: ١٠٣"]], ["الاستعداد للصلاة", ["تأكد من دخول وقت الصلاة، وتطهّر من الحدث والنجاسة، واستُر عورتك بثوب طاهر، وصلِّ في مكان طاهر، واستقبل القبلة قدر استطاعتك. تعلّم الوضوء من دليل الوضوء. احرص على الخشوع والطمأنينة ولا تستعجل الحركات."]], ["النية وتكبيرة الإحرام", ["انوِ بقلبك الصلاة التي ستؤديها؛ لا تحتاج النية إلى لفظ. قف للفرض إن استطعت، وارفع يديك حذو منكبيك أو أذنيك وقل «اللَّهُ أَكْبَرُ»؛ هذه تكبيرة الإحرام. ضع اليد اليمنى على اليسرى في القيام وانظر إلى موضع سجودك."]], ["دعاء الاستفتاح", ["يُستحب بعد تكبيرة الإحرام أن تقول أحد أدعية الاستفتاح الواردة، ومنها هذا الدعاء: وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَاوَاتِ وَالْأَرْضَ حَنِيفًا وَمَا أَنَا مِنَ الْمُشْرِكِينَ، إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ، لَا شَرِيكَ لَهُ وَبِذَٰلِكَ أُمِرْتُ وَأَنَا مِنَ الْمُسْلِمِينَ. ثم استعذ بالله من الشيطان الرجيم، فقل: أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ. دعاء الاستفتاح سنة، ولا يلزم جمع الأدعية معًا."]], ["قراءة الفاتحة", ["اقرأ الفاتحة في كل ركعة إذا كنت منفردًا أو إمامًا، ثم قل «آمين». تعلّمها تدريجيًا، واستعن بمعلّم إن لم تحفظها بعد. وللمأموم خلف الإمام تفصيل وخلاف معروف بين المذاهب السنية؛ اتبع المذهب أو المعلّم الموثوق ولا تتقدم على الإمام. بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ الرَّحْمَٰنِ الرَّحِيمِ مَالِكِ يَوْمِ الدِّينِ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ"]], ["قراءة سورة بعد الفاتحة", ["بعد الفاتحة في الركعتين الأوليين يُستحب أن تقرأ سورة أو آيات أخرى، مثل سورة الإخلاص في الركعة الأولى، وسورة الفلق في الثانية كما في الدرس. ولا تتعين هاتان السورتان. في الركعتين الثالثة والرابعة من الفرض اقتصر على الفاتحة في المثال التعليمي. سورة الإخلاص: بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ قُلْ هُوَ اللَّهُ أَحَدٌ اللَّهُ الصَّمَدُ لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ سورة الفلق: بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ مِنْ شَرِّ مَا خَلَقَ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ"]], ["الركوع", ["قل «اللَّهُ أَكْبَرُ» وانحنِ للركوع، وضع كفيك على ركبتيك وسوِّ ظهرك قدر المستطاع، واطمئن. قل «سُبْحَانَ رَبِّيَ الْعَظِيمِ» ثلاثًا؛ وتكرار التسبيح من السنة."]], ["الرفع من الركوع", ["ارفع رأسك من الركوع حتى تعتدل قائمًا وتطمئن. يقول الإمام والمنفرد «سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ»، ثم يقول «رَبَّنَا وَلَكَ الْحَمْدُ». ويقول المأموم «رَبَّنَا وَلَكَ الْحَمْدُ» عند الرفع، مع مراعاة ما تعلمه من مذهب سني معتبر."]], ["السجود الأول", ["قل «اللَّهُ أَكْبَرُ» واسجد مطمئنًا. يكون السجود على الجبهة مع الأنف، والكفين، والركبتين، وأطراف القدمين حسب الاستطاعة. قل «سُبْحَانَ رَبِّيَ الْأَعْلَى» ثلاثًا، وأكثر من الدعاء لله إن شئت."]], ["الجلوس بين السجدتين", ["قل «اللَّهُ أَكْبَرُ» وارفع من السجود واجلس مطمئنًا، ثم قل «رَبِّ اغْفِرْ لِي»؛ ويجوز تكرارها. لا تنتقل إلى السجدة الثانية قبل الاستقرار في الجلوس."]], ["السجود الثاني", ["قل «اللَّهُ أَكْبَرُ» واسجد ثانيةً كما سجدت أولًا، واطمئن وقل «سُبْحَانَ رَبِّيَ الْأَعْلَى». وبذلك تتم أفعال الركعة."]], ["القيام للركعة التالية", ["قل «اللَّهُ أَكْبَرُ» وقم للركعة التالية. اقرأ الفاتحة وما تيسر بعدها في الركعة الثانية، ثم أتم الركوع والقيام منه والسجدتين كما سبق."]], ["التشهد الأول", ["بعد السجدة الثانية من الركعة الثانية اجلس للتشهد. في الفجر هذا هو الجلوس الأخير؛ أما في المغرب والظهر والعصر والعشاء فبعد التشهد الأول قم مكبرًا للركعة الثالثة. صيغة التشهد: التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَىٰ عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ."]], ["التشهد الأخير والصلاة على النبي", ["بعد الركعة الأخيرة اجلس واقرأ التشهد السابق، ثم صلِّ على النبي ﷺ بالصلاة الإبراهيمية: اللَّهُمَّ صَلِّ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ، اللَّهُمَّ بَارِكْ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ."]], ["الدعاء قبل السلام", ["بعد التشهد الأخير والصلاة على النبي وقبل السلام، يُشرع الدعاء بما ورد، ومنه الاستعاذة من الأربع: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَمِنْ عَذَابِ جَهَنَّمَ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ."]], ["التسليم", ["سلّم عن يمينك قائلًا «السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ»، ثم عن يسارك باللفظ نفسه. وبذلك تنتهي الصلاة."]], ["الذكر بعد الصلاة", ["بعد السلام يُستحب ذكر الله. ومن الصيغ الواردة: «سُبْحَانَ اللَّهِ» ٣٣ مرة، و«الْحَمْدُ لِلَّهِ» ٣٣ مرة، و«اللَّهُ أَكْبَرُ» ٣٣ مرة، ثم تمام المائة مرة واحدة: لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ."]], ["الصلوات الخمس والصلاة جماعة", ["الفجر ركعتان، ثم التشهد الأخير والسلام. المغرب ثلاث ركعات: التشهد الأول بعد الثانية والأخير بعد الثالثة. الظهر والعصر والعشاء أربع ركعات: التشهد الأول بعد الثانية والأخير بعد الرابعة. هذه أعداد الفرائض للمقيم، وللمسافر أحكام قصر معروفة. في الجماعة تابع الإمام ولا تسبقه؛ يجهر الإمام بالقراءة في الفجر وأول ركعتين من المغرب والعشاء، وتكون القراءة سرية في الظهر والعصر وفي بقية ركعات المغرب والعشاء. الصلاة السرية ليست مجرد قراءة بالقلب؛ تعلّم صفتها بحسب قدرتك والمذهب الذي تتبعه."]], ["أحكام مهمة والتيسير", ["الصلاة تحتاج إلى شروطها وأركانها، ومنها دخول الوقت والطهارة، والنية، وتكبيرة الإحرام، والقيام للفرض عند الاستطاعة، والركوع والسجود والطمأنينة. للمذاهب السنية تفصيل معتبر في بعض الأركان والواجبات؛ لا تخلط بينها وبين السنن، مثل دعاء الاستفتاح وقراءة سورة بعد الفاتحة. إذا تركت ركنًا أو شككت فارجع إلى معلّم موثوق في سجود السهو وأحكامه. من عجز عن القيام صلى جالسًا، فإن عجز فعلى جنبه بحسب استطاعته. يستمر المبتدئ في الصلاة وهو يتعلّم، ويسأل معلّمًا موثوقًا عما يعجز عنه، ويتجنب الوسواس."]], ["المصادر", ["القرآن الكريم: النساء ١٠٣، المائدة ٦، الفاتحة. صحيح البخاري: ٧٥٧ في الطمأنينة، و٨٣١ في التشهد، و١١١٧ في صلاة المريض، و٣٣٧٠ في الصلاة على النبي. صحيح مسلم: ٣٩٥ في الفاتحة، و٧٧١ في دعاء الاستفتاح، و٥٨٨ في الدعاء قبل السلام، و٥٩٧ في الذكر بعد الصلاة. قد يختلف ترقيم الأحاديث بين الطبعات."]]]], ["fasting", "الصيام", "moon", [["", ["دليل يشرح صيام رمضان وصيام التطوع والأعذار والقضاء، اعتمادًا على القرآن وكتب الحديث والسنة. توجد مسائل اجتهادية معتبرة بين المذاهب السنية، ويحتاج بعض الأحوال الخاصة إلى سؤال أهل العلم الموثوقين. يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِينَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ سورة البقرة: ١٨٣"]], ["معنى الصيام ومقصده", ["الصيام عبادة لله، أساسها النية والإمساك عن المفطرات من طلوع الفجر الصادق إلى غروب الشمس. غايته تحقيق التقوى وتعظيم الله وتربية النفس على الصبر والرحمة. ليس مجرد الامتناع عن الطعام؛ فيحفظ الصائم لسانه وعمله ويتجنب الظلم والخصومة. وهو أحد أركان الإسلام الخمسة. [١، ٢، ٣]"]], ["متى فُرض صيام رمضان؟", ["تذكر كتب السيرة أن صيام رمضان فُرض في السنة الثانية للهجرة، أي نحو ٦٢٤ ميلادية؛ وهذا تأريخ تاريخي لا يحدده الحديث المذكور هنا. دل القرآن على وجوبه في شهر رمضان، وهو الشهر الذي أُنزل فيه القرآن. [١] وروى الصحيح انتقال الوجوب من عاشوراء إلى رمضان. [٢٩] قد يكون الشهر تسعة وعشرين يومًا أو ثلاثين بحسب ثبوته الشرعي، ولا يُزاد فيه يوم احتياطًا من غير دليل. [٤]"]], ["على من يجب الصوم؟", ["يجب صوم رمضان على المسلم البالغ العاقل القادر المقيم الخالي من الموانع الشرعية. لا يجب على الطفل قبل البلوغ، ويُدرَّب برفق إذا أطاق بلا ضرر. لا يجب على فاقد العقل حال زوال عقله؛ وتختلف التفاصيل بحسب حال العذر. المريض والمسافر ومن لحقه عذر لهما أحكام الرخصة المبينة لاحقًا. [١، ٥]"]], ["النية وكيفية الصوم", ["استحضر في قلبك أنك تصوم لله صوم رمضان أو القضاء؛ لا يلزم التلفظ بعبارة معينة. من الطرق الآمنة في الصوم الواجب عقد النية ليلًا قبل الفجر لكل يوم، وتوجد تفاصيل معتبرة للنية في المذاهب. بعد الفجر أمسك عن المفطرات حتى الغروب، وأدِّ الصلوات في أوقاتها. [٦]"]], ["دخول الشهر ونهايته", ["يبدأ رمضان بثبوت هلاله أو إكمال شعبان ثلاثين يومًا، وينتهي بثبوت هلال شوال أو إكمال رمضان ثلاثين. تختلف الجهات والمذاهب في بعض وسائل الإثبات واختلاف المطالع؛ اتبع إعلان الجهة الإسلامية الموثوقة في بلدك بما يحفظ اجتماع الجماعة، دون تخطئة المختلف اجتهادًا. [٤]"]], ["السحور وبداية الإمساك", ["السحور قبل الفجر سنة وفيه بركة، ويُستحب تأخيره ما لم يُخشَ طلوع الفجر. يبدأ الإمساك عند الفجر الصادق لا عند شروق الشمس. وقت احتياطي قبل الفجر ليس حدًا شرعيًا آخر؛ اتبع تقويمًا محليًا موثوقًا يبيّن الفجر بوضوح. [١، ٧]"]], ["الإفطار عند غروب الشمس", ["ينتهي الصوم بتحقق غروب الشمس في المكان الذي أنت فيه، ويُستحب تعجيل الفطر بعد التحقق. كان النبي ﷺ يفطر على رطب، فإن لم يجد فتمر، فإن لم يجد حسا ماءً. ادعُ الله عند الإفطار وتجنب الإسراف. [٨، ٩]"]], ["آداب الصائم وحقوق الناس", ["الصلاة والصدق والأمانة واجبة في رمضان وخارجه. يتأكد في الصوم ترك الكذب والغيبة والشتم والاعتداء، وكثرة القرآن والذكر والصدقة. المعصية تنقص الأجر وقد تكون كبيرة، لكن لا يُحكم ببطلان الصوم لمجرد كل معصية؛ فرق بين فساد الصوم ونقص ثوابه. [٣]"]], ["ما يبطل الصيام", ["من أبرز المفطرات المتفق عليها: الأكل أو الشرب عمدًا، والجماع عمدًا في نهار الصوم، وخروج دم الحيض أو النفاس. تعمّد إخراج القيء يوجب القضاء عند جمهور أهل العلم، بخلاف القيء الذي غلب الصائم. كما يفسد الصوم بتعمد إنزال المني بالاستمناء عند جمهور الفقهاء، وتختلف تفاصيل بعض صور المباشرة. لا يُسوَّى بين الصور المختلفة بلا علم. [١، ١٠، ١١]"]], ["النسيان والقيء والأمور المباحة", ["من أكل أو شرب ناسيًا فليتوقف حين يتذكر وليتم صومه؛ لا يفسد صومه بذلك. القيء غير المتعمد لا يفسد الصوم في الأصل، والاحتلام أثناء النوم لا يفسده لأنه غير متعمد، ويجب الغسل للصلاة عند خروج المني. يجوز الاغتسال والسواك والمضمضة والاستنشاق برفق مع الاحتراز من تعمد ابتلاع الماء، ولا يضر مجرد الإحساس بالجوع أو العطش. [١٠، ١٢، ١٣]"]], ["الدواء والإجراءات الطبية", ["لا تترك دواءً ضروريًا ولا تعرض نفسك لضرر. الأدوية التي تُؤخذ بالفم في نهار الصوم تفطر، ويمكن للطبيب الموثوق بحث تغيير أوقاتها إن كان ذلك آمنًا. تختلف أحكام البخاخ والحقن والقطرات والإجراءات بحسب حقيقتها والمذهب؛ استشر الطبيب وأهل العلم في الحالة المعينة، ولا تؤخر علاجًا عاجلًا. عند الإفطار لعذر يُنظر في القضاء أو الفدية بحسب القدرة. [١]"]], ["الحيض والنفاس", ["إذا نزل الحيض أو النفاس أثناء النهار أفطرت المرأة، ولا يصح منها الصوم أثناءهما، وتقضي الأيام بعد رمضان دون قضاء الصلوات المتروكة زمن الحيض. إذا تحققت الطهارة قبل الفجر ونوت الصوم، صامت ولو اغتسلت بعد الفجر، مع المبادرة بالغسل لأداء الصلاة. وإذا حصل الطهر بعد الفجر فحكم بقية اليوم محل تفصيل بين الفقهاء، ويُقضى ذلك اليوم. الإفطار هنا طاعة للرخصة وليس ذنبًا. [١٣]"]], ["الحمل والرضاعة", ["الحامل والمرضع إذا خافتا ضررًا معتبرًا على نفسيهما أو على الطفل فلهما رخصة الإفطار؛ تسألان طبيبًا موثوقًا وأهل العلم عن حالتهما. يجب بحث القضاء عند القدرة، وتختلف المذاهب في وجوب الفدية معه في بعض الصور، فلا تُفرض صيغة واحدة على كل حالة. [١٤]"]], ["المرض العارض والمزمن", ["من كان مرضه عارضًا ويخشى أن يزيده الصوم أو يؤخر شفاءه، أو احتاج علاجًا لا يمكن تأخيره، جاز له الفطر ثم يقضي بعد زوال العذر. وإذا خيف ضرر جسيم وجب تجنبه. أما العجز الدائم الذي لا يُرجى زواله فتُبحث فيه فدية إطعام مسكين عن كل يوم عند من قرر ذلك؛ فإن تغيّرت القدرة أو اجتمعت ظروف أخرى فاستشر أهل العلم. [١]"]], ["كبار السن والعجز المستمر", ["الشيخ الكبير أو المريضة الكبيرة إذا عجزا عجزًا مستمرًا عن الصوم، ولا يُرجى قدرتهما، فلهما الفطر ويُطعمان مسكينًا عن كل يوم على ما قرره أهل العلم. تختلف المقادير والصور المعتبرة بحسب المذهب والبلد؛ اطلب بيانًا محليًا موثوقًا، ولا تحمّل نفسك ضررًا. [١، ١٥]"]], ["السفر ومشقة الطريق", ["للمسافر سفرًا معتبرًا شرعًا أن يفطر ويقضي عدد الأيام، وله أن يصوم إذا لم يضره ذلك. إذا شق الصيام مشقة شديدة أو أضر به فالأخذ بالرخصة أولى، وقد يلزم الفطر عند تحقق الضرر. تبدأ الرخصة وتفاصيل انتهائها بحسب أحكام السفر والمذهب، لا بمجرد نية السفر وأنت مقيم. [١، ١٦]"]], ["العمل الشاق والحرارة", ["الأصل أن ينوي العامل الصوم ويأخذ بالأسباب الممكنة كتنظيم الدوام والراحة وتخفيف التعرض للحر. لا يُجعل مجرد اسم المهنة عذرًا عامًا للإفطار من بداية اليوم. إذا حدثت أثناء الصيام مشقة غير محتملة أو خوف ضرر حقيقي لا يمكن دفعه، فله دفع الضرر والفطر بقدر الحاجة ثم قضاء اليوم؛ ويستشير طبيبًا وأهل العلم في حالته. [١]"]], ["قضاء الأيام الفائتة", ["من أفطر بعذر مؤقت يقضي عدد الأيام، متتابعة أو متفرقة، بعد زوال العذر وفي الأيام الجائزة، قبل رمضان التالي إن استطاع. إذا تأخر القضاء لعذر مستمر فلا إثم عليه، وتختلف المذاهب في أحكام التأخير بلا عذر وما قد يضاف إليه. من لا يتذكر العدد يجتهد في تقديره بما يغلب على ظنه. لا يُقضى في يومي العيد، وتُراعى أحكام أيام التشريق. [١، ١٣]"]], ["الفدية والكفارة والفرق بينهما", ["القضاء صوم يوم بدل يوم فائت. الفدية إطعام مسكين في الحالات التي تقررها الشريعة، مثل بعض صور العجز الدائم؛ ولا تستبدل بالقضاء لمن يستطيع القضاء لمجرد التيسير. والكفارة المغلظة حكم آخر في الجماع العمد في نهار رمضان مع شروطه: عتق رقبة، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا. تفاصيل القضاء والكفارة تختلف باختلاف الواقعة والمذاهب؛ تُراجع جهة علمية موثوقة. [١، ١٧]"]], ["صيام التطوع وأحكامه", ["التطوع صوم مشروع غير واجب بأصل الشرع. احرص على إتمامه ولا تشق على نفسك أو تضيع حقًا واجبًا. صوم النذر والكفارة والقضاء ليس كالتطوع المطلق؛ ولكل شروطه. وتختلف تفاصيل نية التطوع وقطعه وقضائه بين المذاهب. [١٨]"]], ["الست من شوال والأيام البيض", ["ستة شوال: ستة أيام من شهر شوال بعد عيد الفطر، ويجوز تفريقها أو تتابعها. الأفضلية وترتيبها مع قضاء رمضان فيهما تفاصيل بين أهل العلم، والحديث ذكر إتباع رمضان بها. الأيام البيض: ثلاثة أيام من كل شهر قمري، هي ١٣ و١٤ و١٥ غالبًا. هذه سنة مختلفة عن ستة شوال، وليست ستة أيام بيض. يُجتنب يوم ١٣ من ذي الحجة لأنه من أيام التشريق إلا في الاستثناء الشرعي المذكور لاحقًا. [١٩، ٢٠]"]], ["الاثنين والخميس وثلاثة أيام كل شهر", ["يُستحب صوم الاثنين والخميس، كما يُستحب صوم ثلاثة أيام من كل شهر قمري؛ ويمكن اختيار الأيام البيض لهذه الثلاثة، ومن صام ثلاثة أخرى من الشهر حصل أصل السنة. إن وافق اليوم يومًا يحرم صومه كالعيد لم يُصَم. [٢٠، ٢١]"]], ["يوم عرفة", ["يوم عرفة هو التاسع من ذي الحجة. يستحب لغير الحاج صومه، وقد ورد أنه يكفّر ذنوب سنتين؛ وبيّن أهل العلم أن التكفير لا يُتخذ ذريعة للإصرار على الكبائر أو حقوق الناس. أما الحاج الواقف بعرفة فالسنة في حقه الفطر ليتقوى على الدعاء، وقد أفطر النبي ﷺ في عرفة. راعِ ثبوت التاريخ في بلدك وما تقرره جهته الإسلامية الموثوقة. [٢٢، ٢٣]"]], ["تاسوعاء وعاشوراء وشهر المحرم", ["عاشوراء هو العاشر من المحرم، ويستحب صوم التاسع معه. ورد في صوم عاشوراء تكفير السنة الماضية، ووردت رغبة النبي ﷺ في صوم التاسع مع العاشر. صوم العاشر وحده جائز عند كثير من أهل العلم مع اختلافهم في إفراده. وشهر المحرم من أفضل الأشهر لصوم التطوع بعد رمضان. [٢٢، ٢٤]"]], ["شعبان وصيام داود وأيام أخرى", ["كان النبي ﷺ يُكثر الصيام في شعبان، ولم يُتم شهرًا كاملًا بالصوم غير رمضان. وصيام داود عليه السلام صوم يوم وفطر يوم لمن يستطيع من غير تضييع الواجبات. ويُستحب العمل الصالح وصوم ما تيسر من الأيام التسعة الأولى من ذي الحجة بحسب الحال، مع مراعاة أن الحاج الواقف بعرفة يُسن له الفطر؛ أما العاشر فهو يوم الأضحى ويحرم صومه. لا يُصام التطوع إذا ترتب عليه ضرر أو تضييع حق واجب. [٢٣، ٢٨]"]], ["الأيام التي يُنهى عن صومها", ["يحرم صوم يوم عيد الفطر ويوم عيد الأضحى. وأيام التشريق هي ١١ و١٢ و١٣ من ذي الحجة، والأصل النهي عن صومها؛ ورُخِّص للحاج المتمتع أو القارن الذي لم يجد الهدي ولم يصم الأيام المطلوبة قبل العيد. ويُكره تخصيص الجمعة وحدها بالتطوع، إلا إن وافقت عادة أو سببًا أو صام معها يومًا قبلها أو بعدها؛ وليس ذلك منعًا لقضاء واجب. [٢٥، ٢٦]"]], ["الصيام في غير بلاد المسلمين", ["حكم الصوم لا يتغير لمجرد الإقامة في بلد غير مسلم. التزم الفجر والغروب في مكانك، واستعن بمسجد أو تقويم إسلامي موثوق يراعي الموقع والتاريخ وطريقة حساب الفجر. إذا اختلف إعلان الهلال أو التقاويم فارجع إلى الجهة الإسلامية الموثوقة محليًا، ولا تتبع مدينة بعيدة لمجرد أنها بلد مسلم. [١]"]], ["البلاد ذات النهار الطويل", ["عندما تظهر علامات الفجر والغروب المعتادة كل يوم، فالأصل الإمساك من الفجر إلى الغروب في موقعك، ولو طال النهار، ما دمت قادرًا بلا ضرر معتبر. لا يجوز اختصار اليوم الطويل تلقائيًا على توقيت مكة أو بلد آخر. إن وقع مرض أو خوف ضرر حقيقي فتطبق رخصته ويُقضى اليوم عند القدرة. [١]"]], ["البلاد التي لا تتعاقب فيها العلامات المعتادة", ["تختلف الصور القطبية: فقد لا تغرب الشمس، أو لا تشرق، أو لا تتميز علامة الفجر الصحيحة في بعض الفصول. لا يصح نقل جدول تقديري واحد لكل هذه الحالات. يلجأ أهل العلم إلى تقدير مواقيت مناسبة عند تعذر العلامات، وقد تختلف طرقهم؛ فاتبع فتوى مجلس أو جهة سنية موثوقة تعرف مدينتك، وتحقق من الفجر والغروب كلما ظهرت علاماتهما. حديث تقدير مواقيت الصلاة في اليوم غير المعتاد أصل استأنس به العلماء في التقدير، وليس نصًا مباشرًا يحدد ساعات الصيام القطبي. [٢٧]"]], ["خطة عملية لصيام مطمئن", ["تحقق من وقت الفجر والمغرب في موقعك، وانْوِ الصيام الواجب ليلًا، وتسحر، وأمسك عن المفطرات، وصلِّ، ثم أفطر بعد تحقق الغروب. سجل أيام القضاء، واحرص على الماء والغذاء الكافي بين الغروب والفجر. إذا ظهرت أعراض مقلقة أو احتجت علاجًا عاجلًا فلا تتأخر عن طلب المساعدة الطبية، واسأل عن الرخصة المناسبة لحالتك."]], ["المصادر", ["[١] القرآن الكريم: البقرة ٢:١٨٣–١٨٧، و٢:١٨٥. [٢] صحيح البخاري ٨؛ صحيح مسلم ١٦. [٣] صحيح البخاري ١٩٠١ و١٩٠٣ و١٨٩٦. [٤] صحيح البخاري ١٩٠٠؛ صحيح مسلم ١٠٨١. [٥] سنن أبي داود ٤٤٠٣. [٦] سنن أبي داود ٢٤٥٤. [٧] صحيح البخاري ١٩٢٣. [٨] صحيح البخاري ١٩٥٤. [٩] سنن أبي داود ٢٣٥٦. [١٠] صحيح البخاري ١٩٣٣. [١١] سنن أبي داود ٢٣٨٠. [١٢] سنن أبي داود ٢٣٦٥–٢٣٦٦؛ صحيح البخاري، كتاب الصوم، باب سواك الرطب واليابس للصائم. [١٣] صحيح مسلم ٣٣٥؛ صحيح البخاري ١٩٢٥–١٩٢٦. [١٤] سنن ابن ماجه ١٦٦٧. [١٥] صحيح البخاري ٤٥٠٥. [١٦] صحيح مسلم ١١٢١؛ صحيح البخاري ١٩٤٦. [١٧] صحيح البخاري ١٩٣٦؛ صحيح مسلم ١١١١. [١٨] صحيح مسلم ١١٥٤. [١٩] صحيح مسلم ١١٦٤. [٢٠] جامع الترمذي ٧٦١. [٢١] جامع الترمذي ٧٤٧. [٢٢] صحيح مسلم ١١٦٢. [٢٣] صحيح البخاري ١٩٨٨. [٢٤] صحيح مسلم ١١٣٤ و١١٦٣. [٢٥] صحيح البخاري ١٩٩٠ و١٩٩٧–١٩٩٨. [٢٦] صحيح مسلم ١١٤٤. [٢٧] صحيح مسلم ٢٩٣٧. [٢٨] صحيح البخاري ١٩٦٩ و١٩٧٦؛ سنن النسائي ٢٣٧٢. [٢٩] صحيح البخاري ٢٠٠٢. قد تختلف أرقام الأحاديث باختلاف الطبعات."]]]], ["zakat", "الزكاة", "heart", [["", ["الزكاة عبادة وحق واجب له أحكام تختلف باختلاف المال وحال صاحبه. يشرح هذا الدليل أصولها اعتمادًا على القرآن وكتب الحديث السنية. وفي بعض التفاصيل خلاف معتبر بين المذاهب السنية، وقد تحتاج المسائل الخاصة إلى سؤال أهل العلم الموثوقين. وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ سورة البقرة: ٤٣"]], ["ما الزكاة؟", ["الزكاة حق واجب في أموال مخصوصة يُصرف إلى مستحقيه تعبّدًا لله، وهي ركن من أركان الإسلام الخمسة. ويرتبط معناها بالتطهير والنماء، وليست مجرد تبرع اختياري. [1، 2]"]], ["مكانتها ومقاصدها", ["أمر الله بإقامة الصلاة وإيتاء الزكاة، وبيّن أن الصدقة تطهّر أصحابها. وتجمع الزكاة بين عبادة الله ورعاية المحتاجين. وأمر النبي ﷺ بأخذها ممن تجب عليه وردّها إلى المستحقين من الفقراء. ولا يسقط أداؤها حقوق الآخرين أو الديون الواجبة. [1، 3]"]], ["الزكاة والصدقة وزكاة الفطر", ["زكاة المال لها شروط تتعلق بنوع المال وصاحبه. أما الصدقة التطوعية فيجوز بذلها زيادة على الواجب، ولا يُشترط لها انتظار النصاب أو الحول. وزكاة الفطر عبادة مستقلة مرتبطة بانتهاء رمضان، ولا تُحسب بنسبة ٢٫٥٪ من الأموال. [2، 4]"]], ["على من تجب الزكاة؟", ["الأصل أن المسلم الذي يملك مالًا زكويًا مستوفيًا لشروطه تجب عليه زكاته، وليست خاصة بالرجال أو الموظفين. وتختلف المذاهب السنية في بعض الشروط، ومنها الزكاة في مال الصغير ومن لا يعقل؛ فيسأل الولي أهل العلم الموثوقين عن حال المال. ولزكاة الفطر أحكامها الخاصة. [3، 4]"]], ["الملكية والنصاب والحول", ["النصاب حد أدنى معتبر لنوع المال الذي تجب فيه الزكاة، وتعتبر الملكية التامة والشروط الأخرى. وفي النقود والذهب والفضة يُراعى عادة مرور حول قمري بعد بلوغ النصاب؛ وتختلف المذاهب في أثر نقص المال وزيادته والخصومات. أما الزروع فلها وقت مختلف: تجب زكاتها عند الحصاد لا بعد حول قمري. [5، 6]"]], ["نصاب الذهب والفضة", ["من الأنصبة المعروفة عشرون دينارًا من الذهب ومئتا درهم من الفضة. ويُقدَّران عادة بنحو ٨٥ جرامًا من الذهب الخالص و٥٩٥ جرامًا من الفضة الخالصة، وقد تختلف المقادير التقريبية والمعايير الفقهية. هذه أوزان وليست مبالغ نقدية ثابتة. ويختلف العلماء في تقدير نصاب النقود بالذهب أو الفضة وبعض تفاصيل التقييم؛ فيُرجع إلى السعر المحلي الحالي وإرشاد موثوق متسق. [5]"]], ["المراجعة السنوية للمال", ["سجّل التاريخ الذي بلغ فيه المال الزكوي النصاب، ثم راجعه بعد حول قمري. قيّم الأموال الزكوية المملوكة يوم الوجوب، وانظر في الديون والخصومات المعتبرة وفق المذهب المتبع، وتحقق من النصاب وبقية الشروط. احتفظ بسجلاتك؛ فالسنة الميلادية ليست مساوية للسنة القمرية."]], ["النقود والمدخرات والمقدار المعتاد", ["تُراجع النقود في اليد والأرصدة والمدخرات المستوفية للشروط مع الأموال النقدية الزكوية ذات الصلة. والمقدار المعتاد في الذهب والفضة والنقود وعروض التجارة المستوفية للشروط هو ربع العشر، أي ٢٫٥٪. وليس هذا المقدار قاعدة عامة لكل الزروع أو الأنعام أو سائر الأموال. وللفوائد والأموال المحرمة أحكام مستقلة؛ فلا تتحول إلى مال حلال بمجرد إخراج الزكاة. [5]"]], ["مثال توضيحي", ["مثال للتوضيح فقط: إذا كان لدى شخص ١٠٬٠٠٠ وحدة نقدية من المال الزكوي المستوفي للنصاب والحول بعد تطبيق الأحكام المناسبة، فزكاته ٢٥٠ وحدة، أي ٢٫٥٪. يجب التحقق من قيمة النصاب الحالية بالعملة المحلية. ويفترض المثال أن الرقم المذكور هو المبلغ الزكوي، ولا يحدد الديون التي يجوز خصمها."]], ["الذهب والفضة والحلي", ["للذهب والفضة أنصبة معلومة ومقدارهما ربع العشر عند تحقق الشروط. يُنظر إلى مقدار المعدن النفيس الخالص، فلا يُعامل الوزن المختلط أو وزن الذهب عيار ١٨ كأنه كله ذهب خالص. وتختلف المذاهب في زكاة الحلي المباح المعد للاستعمال الشخصي؛ فيُسأل عن الحلي والمدخر للاستثمار دون نسبة رأي واحد إلى جميع العلماء. [5]"]], ["العقارات والممتلكات الشخصية", ["مسكن الشخص وأثاثه المعتاد وثيابه وسيارته الخاصة لا تصبح عروض تجارة لمجرد امتلاكها. ويختلف حال العقار المعد للبيع تجارة عن المسكن، أو العقار المؤجّر، أو الأرض التي لم تُعد للتجارة. وتحتاج الملكية والنية وتغيّرها إلى تقييم دقيق."]], ["عروض التجارة والمخزون", ["في عروض التجارة الحقيقية تُقدَّر قيمة السلع المعدة للبيع، وتُراجع معها نقود التجارة والديون المرجوة وفق أحكامها. أدوات الاستعمال الشخصي أو أدوات العمل تختلف عن المخزون المعد للبيع. وتختلف تفاصيل التقييم والديون باختلاف النشاط والمذهب؛ فلا تُطبق معادلة واحدة دون تحقق."]], ["الأسهم والصناديق والاستثمارات", ["تختلف الأسهم وصناديق الاستثمار والمعاشات في طبيعة الملكية وإمكان الانتفاع والأصول التي تمثلها. وقد تختلف الأسهم المعدة للبيع عن الاستثمار طويل الأجل، كما تُراجع الأرباح والنقود المتاحة وفق أحكامها. اطلب بيانًا بالأصول وإرشادًا موثوقًا؛ فليست قيمة السوق كلها أو الأرباح وحدها أو نسبة آلية واحدة مناسبة لكل حالة."]], ["الديون والمال الذي لك عند الآخرين", ["الدين الثابت في ذمتك لا يُخصم كله تلقائيًا؛ فالمذاهب تختلف فيما يؤثر من الديون والمبالغ المستحقة وأنواع الأموال. والمال الذي لك عند غيرك قد يكون مرجوّ السداد أو متعثرًا؛ وتؤثر الملكية وتوقع السداد ووقت الإخراج في الحكم. سجّل كل حالة على حدة واسأل، دون افتراض إهمال كل الديون أو خصمها كلها."]], ["الرواتب والمدخرات الجديدة", ["الراتب ليس ضريبة زكاة شهرية مستقلة بمجرد قبضه. وما يبقى منه مدخرًا يُنظر فيه مع المال الزكوي. ويختلف العلماء في ضم الزيادات إلى موعد الزكاة القائم أو حساب حول مستقل لبعضها. ويمكن الاحتفاظ بسجل واضح وسؤال أهل العلم، وقد يُيسّر تعجيل الزكاة عند جوازه."]], ["الزروع والثمار", ["للزروع والثمار أحكامها، وتُراجع عند الحصاد دون انتظار حول قمري. ورد نصاب خمسة أوسق؛ والوسق ستون صاعًا، فالخمسة ثلاثمئة صاع بالكيل، ويختلف الوزن باختلاف المحصول. وتختلف المذاهب في أنواع الزروع واعتبار النفقات. وورد العشر فيما سُقي بالمطر أو الماء الجاري ونحوه، ونصف العشر فيما سُقي بمؤونة. أما الري المختلط والنفقات الحديثة فتحتاج إلى إرشاد؛ فلا تنطبق عليها آليًا نسبة النقود أو قيمة واحدة بالكيلوجرام. [6، 7، 8]"]], ["الأنعام", ["للإبل والبقر والغنم السائمة أنصبة ومقادير وردت في السنة، وتؤثر الأنواع والأعداد والغرض والعلف والملكية في الحكم. فمن النصوص نصاب خمس من الإبل، وللغنم جدول مستقل. لا تُطبق نسبة ٢٫٥٪ على جميع الحيوانات آليًا، ولا يُفترض دخول كل حيوان في الزكاة؛ بل يُسأل عن الجدول المناسب. [6، 9]"]], ["أموال أخرى وحالات خاصة", ["قد توجد أحكام خاصة للمعادن والركاز وأموال أخرى، وتختلف مقاديرها وشروطها عن المدخرات المعتادة. إذا لم تتضح حالة في هذا الدليل فاسأل أهل العلم، ولا تفترض أن نسبة ٢٫٥٪ تنطبق على كل شيء."]], ["من يستحق الزكاة؟", ["حدد القرآن مصارف الزكاة في ثمانية أصناف: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَابْنِ السَّبِيلِ فَرِيضَةً مِنَ اللَّهِ وَاللَّهُ عَلِيمٌ حَكِيمٌ سورة التوبة: ٦٠. [10]"]], ["شرح الأصناف الثمانية", ["الفقراء والمساكين من لا تكفيهم مواردهم، والعاملون عليها يتولون شؤونها بشروطهم، وللمؤلفة قلوبهم أحكامهم. وتشمل المصارف المذكورة الرقاب والغارمين المستحقين، وسبيل الله وابن السبيل وفق أحكام الفقه السني. للاستحقاق والتوزيع تفاصيل، وتختلف المذاهب السنية في عدد الأصناف أو المستحقين الذين تُصرف إليهم الزكاة. [10]"]], ["الزكاة للأقارب والأسرة", ["قد يجتمع في القريب المستحق أجر الصدقة وصلة الرحم. وهناك قيود فيمن تجب نفقتهم على المزكي، وخلاف بين المذاهب في بعض الحالات، ومنها دفع الزوجة إلى زوجها المستحق. سألت زينب عن زوجها والأيتام في حجرها، فأخبرها النبي ﷺ بأجر الصدقة والقرابة. اسأل عن صلة القرابة والحاجة في حالتك. [11]"]], ["قيود أخرى وحاجة المجتمع", ["الزكاة أمانة تُصرف في مصارفها الشرعية، ولا يكفي استحسان المشروع وحده للحكم باستحقاقه. ولآل النبي ﷺ وبعض الحالات الأخرى أحكام مخصوصة وتفاصيل معروفة. ويمكن الاستعانة بجمعية محلية موثوقة للتحقق من الاستحقاق، وقد يجوز نقل الزكاة إلى مكان آخر وفق الأحكام والحاجة. تحقق من طريقة التوزيع والجهة. [3، 10، 12]"]], ["متى وكيف تدفع الزكاة؟", ["إذا وجبت الزكاة فأخرجها دون تأخير غير مبرر مع نية الزكاة. ويجيز بعض أهل العلم تعجيلها عند تحقق شروطه. رمضان وقت مبارك للصدقة، لكن من حل حول زكاته في شهر آخر لا يؤخرها تلقائيًا إلى رمضان. احتفظ بسجل المبالغ والجهات المدفوع إليها."]], ["النية وحسن توزيع الزكاة", ["النية محلها القلب، فيقصد المزكي أداء الزكاة الواجبة دون اشتراط لفظ معين. أعطِ المستحق باحترام، دون إذلال أو كشف خصوصيته بغير حاجة. ويمكن توكيل جهة موثوقة في التوزيع. والضرائب والتبرعات ليست زكاة تلقائيًا؛ بل يُنظر في النية والمصارف والأحكام."]], ["الزكاة الفائتة والأخطاء", ["إذا فاتتك زكاة سابقة أو أخطأت في حسابها، فاجمع ما تستطيع من السجلات وقدّر تقديرًا معقولًا، واستغفر الله وأخرج ما وجب في أقرب وقت ممكن. وقد تحتاج الديون المعقدة والسجلات المفقودة والحسابات المختلف فيها إلى إرشاد خاص. والصدقة التطوعية السابقة لا تتحول تلقائيًا إلى زكاة دون النية اللازمة."]], ["زكاة الفطر: على من وما مقدارها؟", ["زكاة الفطر مستقلة عن زكاة المال السنوية. فرض النبي ﷺ صاعًا من طعام كالتمر أو الشعير عن المسلمين، صغيرهم وكبيرهم. والصاع مكيال للحجم يختلف وزنه باختلاف الطعام. ولمسؤولية النفقة والقدرة وصور الإخراج تفاصيل، وتختلف المذاهب السنية في إخراج القيمة النقدية؛ فاتبع إرشادًا محليًا موثوقًا. [4، 13]"]], ["زكاة الفطر: وقتها ومستحقوها", ["أخرج زكاة الفطر قبل صلاة العيد للمستحقين مباشرة، أو من خلال وكيل موثوق مخوّل يستطيع توزيعها في وقتها. ويجوز تعجيلها ضمن حدود بحثها العلماء؛ وورد الإخراج قبل العيد بيوم أو يومين. وهي عون للمحتاجين. وإذا فات الوقت فلا يُهمل الواجب؛ اسأل عن حالتك وأدّ ما يلزم. [13، 14]"]], ["خطوات عملية", ["١. احصر الأموال وتحقق من ملكيتها. ٢. ميّز الأموال الزكوية ومواعيد وجوبها. ٣. تحقق من قيمة النصاب الحالية والحول القمري حيث يُشترط. ٤. طبّق المقدار الصحيح والخصومات المعتبرة. ٥. انوِ الزكاة واختر المستحقين وسجّل الدفع. ٦. راجع زكاة الفطر مستقلة في نهاية رمضان. وعند الإشكال اسأل أهل العلم الموثوقين."]], ["المصادر", ["[1] القرآن الكريم: البقرة ٤٣، والتوبة ١٠٣. [2] صحيح البخاري ٨، وصحيح مسلم ١٦. [3] صحيح البخاري ١٤٩٦. [4] صحيح البخاري ١٥٠٣. [5] سنن أبي داود ١٥٧٣. [6] صحيح البخاري ١٤٠٥، والقرآن الكريم: الأنعام ١٤١. [7] صحيح البخاري ١٤٨٣، وصحيح مسلم ٩٨١. [8] صحيح البخاري ١٤٨٤. [9] صحيح البخاري ١٤٥٤. [10] القرآن الكريم: التوبة ٦٠. [11] صحيح البخاري ١٤٦٦. [12] صحيح مسلم ١٠٧٢. [13] صحيح البخاري ١٥٠٣ و١٥٠٩. [14] صحيح البخاري ١٥١١. قد تختلف أرقام الأحاديث بين الطبعات."]]]], ["hajj", "الحج والعمرة", "kaaba", [["", ["الحج رحلة عبادة إلى بيت الله الحرام، تجمع التوحيد والذكر والصبر والإحسان. يشرح هذا الدليل المناسك خطوة خطوة، مع الإشارة إلى الاختلاف المعتبر بين المذاهب السنية. تعلّم أحكام نسكك قبل السفر، واسأل عن حالتك عند الحاجة. وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا سورة آل عمران: ٩٧"]], ["معنى الحج ومكانته", ["الحج قصد البيت الحرام لأداء المناسك في وقتها عبادةً لله. وهو ركن من أركان الإسلام، ويجب في العمر مرة على المسلم المستطيع، والتطوع بعد ذلك فضل. ليس كل من تأخر قادرًا أو عاصيًا؛ فالاستطاعة تُقدَّر بحسب حاله. [1، 2]"]], ["على من يجب؟", ["تشمل الاستطاعة القدرة البدنية والمالية وأمن الطريق وما يلزم من حاجات من تلزمه نفقتهم، مع مراعاة الديون والأنظمة والظروف. وتختلف بعض تفاصيل الشروط بين المذاهب السنية. المريض أو العاجز عجزًا دائمًا يسأل عن الحج بالنيابة وشروطه؛ ولا يكلَّف الإنسان ما لا يستطيع. [1، 3]"]], ["الإخلاص والتوبة وحقوق الناس", ["انوِ الحج لله، وتب من الذنوب، واقضِ ديونك أو نظّمها بإذن أصحابها، وردّ الأمانات، واكتب الوصية عند الحاجة، واختر نفقة حلالًا. تعلم المناسك قبل السفر، واطلب العفو ممن ظلمت، مع المحافظة على حقوق الأسرة والعمل."]], ["الاستعداد للسفر والصحة", ["تحقق من التصاريح ووثائق السفر وخطة المجموعة والإقامة والتنقل، واكتب أرقام الطوارئ، وخذ الدواء وماء الشرب ووسائل الوقاية من الحر. اسأل طبيبك عن المرض والحمل وكبار السن. خطط لمرافقة من يحتاج للمساعدة وتجنب المزاحمة."]], ["المدينة أولًا أو بعد الحج", ["زيارة المسجد النبوي والصلاة فيه فضل عظيم، لكنها ليست ركنًا من الحج ولا شرطًا لصحته. يجوز زيارة المدينة قبل المناسك أو بعدها أو عدم زيارتها. سلّم بأدب على النبي ﷺ وصاحبيه من الموضع المسموح بلا تزاحم، وادعُ الله وحده. [4]"]], ["من المدينة إلى مكة", ["لا إحرام لمجرد الوصول إلى المدينة. من خرج منها إلى مكة يريد حجًا أو عمرة يحرم عند ميقات ذي الحليفة، المعروف بأبيار علي، أو قبل تجاوزه، بعد اختيار نسكه. جهّز اللباس قبل الميقات، لكن لا تبدأ محظورات الإحرام إلا بنية الدخول في النسك. [5]"]], ["المواقيت والوصول جوًا", ["للمدينة ذو الحليفة، وللشام الجحفة، ولنجد قرن المنازل، ولليمن يلملم، ولأهل العراق ذات عرق، ولمن مر عليها مريدًا النسك. جهّز إحرامك قبل الصعود للطائرة، وانوِ عند محاذاة الميقات أو قبلها احتياطًا؛ لا تنتظر الهبوط إذا تجاوزته. استفسر عن مسارك. [5]"]], ["الأنساك الثلاثة", ["التمتع: عمرة في أشهر الحج، ثم تحلل، ثم إحرام جديد بالحج. الإفراد: إحرام بالحج وحده. القِران: إحرام بالحج والعمرة معًا، ويبقى المحرم حتى تحلل الحج. للتمتع والقِران هدي بشروطه، بخلاف المفرد. اسأل عن أحكام حالك قبل اختيار النسك. [6]"]], ["الاستعداد للإحرام", ["يستحب الاغتسال والتنظف قبل الإحرام، وللرجل أن يتطيب في بدنه قبل عقده دون تطييب ثوب الإحرام. يلبس الرجل إزارًا ورداءً ونعلين، وتلبس المرأة لباسًا ساترًا معتادًا غير لافت دون تخصيص لون. تغتسل الحائض والنفساء للإحرام أيضًا. [7]"]], ["النية والتلبية", ["النية في القلب للدخول في العمرة أو الحج، ويستحب التلفظ بالنسك والتلبية: لبيك اللهم لبيك، لبيك لا شريك لك لبيك، إن الحمد والنعمة لك والملك، لا شريك لك. يستمر الحاج في التلبية إلى رمي جمرة العقبة، والمعتمر حتى يشرع في الطواف. الاشتراط عند خوف مانع له تفصيل. [8]"]], ["محظورات الإحرام المشتركة", ["بعد الدخول في الإحرام يُجتنب الطيب، وإزالة الشعر أو قص الأظافر، وعقد النكاح، والجماع ودواعيه، وقتل صيد البر أو الإعانة عليه، وسائر ما ورد من المحظورات. الغسل وتغيير ثياب الإحرام جائزان، ويُتجنب المعطر. الوقوع في محظور لا يعني تلقائيًا بطلان الحج؛ تختلف أحكام الخطأ والحاجة والفدية. [9]"]], ["ما يختص بلباس الرجل والمرأة", ["لا يلبس الرجل المحرم القميص والسراويل والعمامة وما فُصّل للجسم على الوجه الممنوع، ولا يغطي رأسه تغطية ملاصقة؛ الخياطة نفسها ليست علة المنع، فيجوز الحزام والساعة والصندل المناسب. لا تنتقب المرأة المحرمة ولا تلبس القفازين، ولها ستر وجهها عن الأجانب بغطاء غير النقاب عند الحاجة، مع مراعاة الخلاف السني في صفته. [10]"]], ["الأخلاق والسلامة", ["اجتنب الرفث والفسوق والجدال المؤذي، والزحام والدفع والخصام، واحفظ اللسان والنظر، وأعن الضعيف واحترم رجال التنظيم. لا تُؤذِ أحدًا لتقبيل الحجر أو أداء سنة، ولا تترك الصلاة أو فرائضك من أجل التصوير والتسوق. الحج عبادة ورحمة وسكينة. [1]"]], ["الصيد والحيوانات المؤذية", ["يحرم على المحرم صيد البر وإعانة الصائد عليه، وللحرم أحكام أخرى لحماية صيده ونباته. هذا لا يعني تحريم دفع الحيوان المؤذي أو قتله عند الحاجة؛ وقد ورد ذكر الوزغ المعروف بالبرص في الحديث. تجنب الأذى والعبث بالحيوان، واسأل عن الحكم الخاص عند الإشكال. [9، 16]"]], ["عمرة المتمتع: الطواف", ["عند الوصول إلى مكة يتوجه المعتمر إلى المسجد الحرام، فيطوف بالبيت سبعة أشواط تبدأ بمحاذاة الحجر الأسود والبيت عن يساره. إن شق الوصول أشار إليه دون مزاحمة. يُبقي حِجر إسماعيل داخل مسار الطواف. لا يلزم دعاء خاص بكل شوط. بعد الطواف يصلي ركعتين إن تيسر. [8]"]], ["الطهارة وآداب الطواف", ["تطهر من الحدث والنجاسة قبل الطواف احتياطًا واتباعًا لفعل النبي ﷺ، مع العلم بوجود خلاف سني في اشتراط الوضوء للطواف. تصلي المرأة بعد الطهر والغسل، وتؤخر الطواف حال الحيض والنفاس. لا تقبيل للحجر أو لمس للركن إذا أدى إلى أذى، ولا تلمس أجزاء البيت اعتقادًا أن ذلك لازم."]], ["عمرة المتمتع: السعي والتحلل", ["يسعى بين الصفا والمروة سبعة أشواط: من الصفا إلى المروة شوط، والعودة شوط، وينتهي السابع عند المروة. ثم يحلق الرجل أو يقصر شعر رأسه، وتقصر المرأة من أطراف شعرها ولا تحلقه. بذلك يتحلل المتمتع من عمرته حتى يحرم بالحج؛ أما القارن أو المفرد فيبقى محرمًا وفق نسكه. [8]"]], ["الإحرام بالحج يوم التروية", ["في الثامن من ذي الحجة يحرم المتمتع بالحج من مكان إقامته بمكة أو حيث هو، ويلبي. ويتوجه الحجاج إلى منى إن تيسر، فيصلون الظهر والعصر والمغرب والعشاء والفجر في أوقاتها، ويقصر المسافر الرباعية دون جمع هناك على صفة فعل النبي ﷺ. فوات هذه السنة لا يعني بطلان الحج. [8]"]], ["التاسع: الوقوف بعرفة", ["بعد طلوع الشمس يوم التاسع يتوجه الحاج إلى عرفة، ويتحقق من أنه داخل حدودها لا داخل وادي عُرنة. يصلي الظهر والعصر قصرًا وجمع تقديم بحسب إمكانه، ثم يكثر الذكر والدعاء مستقبل القبلة إلى الغروب. الوقوف بعرفة ركن عظيم، ولا يشترط صعود جبل الرحمة. يبدأ الوقوف بعد زوال يوم التاسع، ويمتد إلى فجر يوم النحر، مع اختلاف في بداية وقته؛ ومن وقف نهارًا يمكث إلى الغروب ما استطاع. ومن فاته الوقوف حتى الفجر يسأل فورًا عن حكم التحلل والقضاء. [8]"]], ["ليلة مزدلفة", ["بعد غروب التاسع يتوجه الحاج بسكينة إلى مزدلفة، ويصلي المغرب والعشاء جمعًا هناك، ويبيت بحسب الاستطاعة وترتيبات المجموعة. رُخّص للضعفاء ومن معهم بالتقدم ليلًا؛ وللمبيت وحدّه وأحكام العذر تفاصيل بين المذاهب. بعد الفجر يذكر الله حتى يسفر ثم ينصرف إلى منى قبل طلوع الشمس. [8]"]], ["العاشر: رمي جمرة العقبة", ["يوم النحر يرمي جمرة العقبة الكبرى بسبع حصيات صغيرات، واحدة بعد أخرى، ويكبّر مع كل حصاة. الهدف إصابة موضع الرمي لا الشاخص نفسه؛ لا تُلقِ الحجارة على الناس أو الأشياء. لا يشترط غسل الحصى، واتبع التعليمات وأوقات التفويج الآمنة. [8]"]], ["الهدي والفدية", ["يجب هدي التمتع والقِران على من تحققت شروطه، ومن لم يجد صام ثلاثة أيام في الحج وسبعة إذا رجع كما في القرآن. ليس كل حاج مطالبًا بالهدي نفسه، ولا يُخلط الهدي الواجب بفدية محظور الإحرام. يمكن توكيل جهة موثوقة للذبح في وقته ومكانه وتوزيعه؛ اسأل عن تفاصيل حالك. [6]"]], ["الحلق أو التقصير والتحلل الأول", ["بعد الرمي والهدي لمن يلزمه، يحلق الرجل رأسه أو يقصره، والحلق أفضل. تقصر المرأة من أطراف شعرها ولا تحلقه. ثم يتحلل الحاج التحلل الأول بحسب ما يشترطه مذهبه، فتباح له غالب المحظورات ويبقى الجماع ممنوعًا حتى التحلل الكامل. تفاصيل ترتيب الأعمال وما يحصل به التحلل محل خلاف، فاسأل مرشدًا موثوقًا. [8، 11]"]], ["طواف الإفاضة والسعي", ["ينزل الحاج إلى مكة فيطوف طواف الإفاضة، وهو من أركان الحج. ثم يسعى سعي الحج لمن يلزمه، ومنه المتمتع؛ وللمفرد والقارن تفصيل إن قدّما السعي مع طواف القدوم. بإتمام ما يلزم للتحلل الكامل تباح بقية المحظورات. يجوز تقديم بعض أعمال يوم النحر وتأخيرها فيما وردت فيه الرخصة. [8، 11]"]], ["أيام التشريق", ["يبيت الحاج بمنى ليالي أيام التشريق بحسب الواجب والقدرة والأعذار، ويرمي كل يوم الجمرات الثلاث بعد الزوال: الصغرى ثم الوسطى ثم الكبرى، سبع حصيات لكل واحدة مع التكبير. يدعو بعد الصغرى والوسطى بعيدًا عن الزحام، ولا يقف للدعاء بعد الكبرى. للأوقات والأعذار تفاصيل معتبرة. [12]"]], ["التعجل أو التأخر", ["يجوز التعجل بعد رمي اليوم الثاني عشر والخروج من منى قبل غروب شمسه وفق أحكام التعجل، ويجوز التأخر إلى الثالث عشر ورمي الجمرات فيه، وهو أفضل لمن تيسر له. من تأخر لغروب الشمس قهرًا أو وقع في ازدحام يسأل عن حالته، ولا يعرّض نفسه أو غيره للخطر. [13]"]], ["طواف الوداع والسفر", ["قبل مغادرة مكة بعد الحج يجعل الحاج آخر عهده بالبيت طواف الوداع، ويُرخّص للحائض والنفساء في تركه إذا أتمتا طواف الإفاضة. ولا يسقط طواف الإفاضة عن الحائض؛ فإن لم تؤده تحتاج إلى ترتيب حالتها. بعد الوداع يغادر دون انشغال غير لازم، ثم يمكنه زيارة المدينة أو الرجوع إلى بلده. [14]"]], ["الحيض والنفاس", ["تحرم الحائض والنفساء، وتقف بعرفة وتذكر الله وتفعل المناسك، لكنها لا تطوف بالبيت حتى تطهر وتغتسل. إن خشيت فوات عرفة أو اضطرار السفر، فلا تترك الإحرام أو تفترض التحلل بنفسها؛ تسأل عن مسارها والضرورة والاختلاف الفقهي. أحكام السعي متصلة بما قبله من طواف. [15]"]], ["العجز والمرض", ["خذ الرخص المشروعة، واستعمل العربة أو المرافق عند الحاجة، واتبع التوجيه الطبي والتنظيمي. لبعض المعذورين أحكام في الرمي والتوكيل والمبيت، ويختلف تطبيقها؛ ولا يُوكَّل عن القادر لمجرد الراحة دون تحقق الحكم. اطلب المساعدة مبكرًا ولا تؤخر علاجًا عاجلًا."]], ["الأركان والواجبات والأخطاء", ["يُفرَّق بين الركن والواجب والسنة، وتختلف المذاهب في تصنيف بعض الأعمال وتفاصيل أثر تركها. الوقوف بعرفة وطواف الإفاضة من أركان الحج، والإحرام أساس الدخول في النسك، وللسعي والحلق وتفاصيلهما خلاف. لا يُحكم بالبطلان أو الفدية لكل خطأ دون معرفة النسك والوقت والقدرة؛ اسأل أهل العلم قبل المغادرة."]], ["بعد الحج والعودة", ["احمد الله واسأله قبول العمل، وواصل الصلوات والتوبة وحسن الخلق، وردّ الحقوق وواظب على أعمال الخير. يجوز السفر بعد إكمال المناسك والوداع وما يلزم من الترتيبات، ولا يجب البقاء عددًا معينًا من الأيام بعد انتهاء الحج. لا تجعل اللقب أو المظهر دليل قبول؛ فالعبرة بإخلاص العمل والاستقامة."]], ["قائمة مختصرة للمتابعة", ["١. استعدّ وتحقق من القدرة والتصاريح. ٢. اختر النسك وأحرم عند الميقات. ٣. أتمم العمرة وتحلل إن كنت متمتعًا. ٤. أحرم بالحج وتوجه إلى منى يوم ٨. ٥. قف بعرفة يوم ٩ ثم بت بمزدلفة. ٦. يوم ١٠: جمرة العقبة والهدي لمن يلزمه والحلق أو التقصير وطواف الإفاضة والسعي الواجب. ٧. ارمِ الجمرات أيام التشريق. ٨. قبل مغادرة مكة طف للوداع ما لم تكن معذورًا. راجع أحكام الأعذار والترتيب مع مرشد موثوق."]], ["المصادر", ["[1] القرآن الكريم: آل عمران ٩٧، والبقرة ١٩٧ و٢٨٦. [2] صحيح البخاري ٨، وصحيح مسلم ١٦. [3] صحيح البخاري ١٥١٣ و١٨٥٢. [4] صحيح البخاري ١١٨٩ و١١٩٠، وصحيح مسلم ١٣٩٧. [5] صحيح البخاري ١٥٢٦، وصحيح مسلم ١١٨١. [6] القرآن الكريم: البقرة ١٩٦، وصحيح مسلم ١٢٢٧. [7] صحيح مسلم ١٢١٨ أ، وصحيح البخاري ١٥٣٩. [8] صحيح مسلم ١٢١٨ أ، وصحيح البخاري ١٦٤٦. [9] القرآن الكريم: البقرة ١٩٦–١٩٧ والمائدة ٩٥، وصحيح البخاري ١٨١٤. [10] صحيح البخاري ١٥٤٢ و١٨٣٨. [11] صحيح البخاري ١٧٣٦، وصحيح مسلم ١٣٠٦. [12] صحيح البخاري ١٧٥١ و١٧٥٣. [13] القرآن الكريم: البقرة ٢٠٣. [14] صحيح البخاري ١٧٥٥ و١٧٦٠. [15] صحيح البخاري ٣٠٥، وصحيح مسلم ١٢١١. [16] صحيح البخاري ١٨٢٩، وصحيح مسلم ٢٢٣٨. قد تختلف أرقام الأحاديث بين الطبعات."]]]]]; })();
